-- Notifications are generated by database events so all clients receive the
-- same alerts regardless of which UI action caused the change.

drop policy if exists "notifications: service insert" on public.notifications;
drop policy if exists "notifications: admin insert" on public.notifications;
create policy "notifications: admin insert"
  on public.notifications for insert
  to authenticated
  with check (public.is_admin());

drop policy if exists "notifications: own delete" on public.notifications;
create policy "notifications: own delete"
  on public.notifications for delete
  using (user_id = auth.uid());

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1
       from pg_publication_tables
       where pubname = 'supabase_realtime'
         and schemaname = 'public'
         and tablename = 'notifications'
     ) then
    alter publication supabase_realtime add table public.notifications;
  end if;
end
$$;

create or replace function public.notify_course_material_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_type text;
  v_course_name text;
begin
  if new.publication_status <> 'PUBLISHED' or not new.is_active then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_type := 'NEW_MATERIAL';
  elsif old.publication_status <> 'PUBLISHED' then
    v_type := 'NEW_MATERIAL';
  elsif old.version is distinct from new.version
     or old.title is distinct from new.title
     or old.description is distinct from new.description then
    v_type := 'MATERIAL_UPDATED';
  else
    return new;
  end if;

  select name into v_course_name
  from public.courses
  where id = new.course_id;

  insert into public.notifications (user_id, title, message, type, resource_type, resource_id)
  select enrollment.student_id,
         case when v_type = 'NEW_MATERIAL' then 'New course material' else 'Course material updated' end,
         format('%s is available for %s.', new.title, coalesce(v_course_name, 'your course')),
         v_type,
         'courses',
         new.course_id
  from public.course_enrollments enrollment
  where enrollment.course_id = new.course_id
    and enrollment.status = 'ACTIVE'
    and enrollment.student_id <> new.uploaded_by;

  return new;
end;
$$;

drop trigger if exists course_material_notification on public.course_materials;
create trigger course_material_notification
  after insert or update of publication_status, version, title, description, is_active
  on public.course_materials
  for each row execute function public.notify_course_material_change();

create or replace function public.notify_borrowing_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_title text;
  v_notification_title text;
  v_message text;
  v_type text;
begin
  select title into v_title
  from public.books
  where id = new.book_id;

  if tg_op = 'INSERT' then
    v_notification_title := 'Book issued';
    v_message := format('"%s" is due on %s.', coalesce(v_title, 'Your book'), new.due_date);
    v_type := 'BOOK_ISSUED';
  elsif old.status is distinct from new.status and new.status = 'OVERDUE' then
    v_notification_title := 'Book overdue';
    v_message := format('Please return "%s". Its due date was %s.', coalesce(v_title, 'your book'), new.due_date);
    v_type := 'BOOK_OVERDUE';
  elsif old.status is distinct from new.status and new.status = 'RETURNED' then
    v_notification_title := 'Book returned';
    v_message := format('Your return of "%s" has been recorded.', coalesce(v_title, 'the book'));
    v_type := 'BOOK_RETURNED';
  else
    return new;
  end if;

  insert into public.notifications (user_id, title, message, type, resource_type, resource_id)
  values (new.student_id, v_notification_title, v_message, v_type, 'borrowings', new.id);

  return new;
end;
$$;

drop trigger if exists borrowing_notification on public.borrowings;
create trigger borrowing_notification
  after insert or update of status on public.borrowings
  for each row execute function public.notify_borrowing_change();

create or replace function public.notify_reservation_ready()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_book_title text;
begin
  if new.status <> 'READY' then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status = 'READY' then
    return new;
  end if;

  select title into v_book_title
  from public.books
  where id = new.book_id;

  insert into public.notifications (user_id, title, message, type, resource_type, resource_id)
  values (
    new.student_id,
    'Reserved book is ready',
    format('"%s" is ready for pickup at the library.', coalesce(v_book_title, 'Your reserved book')),
    'RESERVATION_READY',
    'books',
    new.book_id
  );

  return new;
end;
$$;

drop trigger if exists reservation_ready_notification on public.reservations;
create trigger reservation_ready_notification
  after insert or update of status on public.reservations
  for each row execute function public.notify_reservation_ready();

create or replace function public.notify_research_review()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_type text;
  v_message text;
begin
  if tg_op <> 'UPDATE' or old.approval_status is not distinct from new.approval_status then
    return new;
  end if;

  if new.approval_status = 'APPROVED' then
    v_type := 'RESEARCH_APPROVED';
    v_message := format('Your research submission "%s" has been approved.', new.title);
  elsif new.approval_status = 'REJECTED' then
    v_type := 'RESEARCH_REJECTED';
    v_message := format('Your research submission "%s" was not approved. %s',
      new.title, coalesce(new.rejection_reason, 'Please contact the administrator for details.'));
  else
    return new;
  end if;

  insert into public.notifications (user_id, title, message, type, resource_type, resource_id)
  values (
    new.submitted_by,
    case when v_type = 'RESEARCH_APPROVED' then 'Research approved' else 'Research review update' end,
    v_message,
    v_type,
    'research',
    new.id
  );

  return new;
end;
$$;

drop trigger if exists research_review_notification on public.research_resources;
create trigger research_review_notification
  after update of approval_status on public.research_resources
  for each row execute function public.notify_research_review();
